__NUXT_JSONP__("/th/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"th",pageTitle:"เปลี่ยนสถานะ | Mentor Language Institute",pageDescription:"ขอบคุณที่ท่านสนใจเข้าเรียนกับ MLI. หน้านี้ใช้สำหรับผู้ที่อยู่ในสหรัฐฯโดยไม่มีวีซ่า F1 (นักเรียน) และต้องการเปลี่ยนเป็นสถานะ F1.",title:"เปลี่ยนสถานะ",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["ขอบคุณที่ท่านสนใจเข้าเรียนกับ MLI.\u003Cbr \u002F\u003E หน้านี้ใช้สำหรับผู้ที่อยู่ในสหรัฐฯโดยไม่มีวีซ่า F1 (นักเรียน) และต้องการเปลี่ยนเป็นสถานะ F1.","หากคุณต้องการสมัครกรุณาดำเนินการต่อไป:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-th.png",link:"\u002Fth\u002Fadmission"}},applicationSteps:{title:"ขั้นตอนการสมัคร",description:["ขั้นตอนการสมัครจะขึ้นอยู่กับประเทศ สัญชาติ หลักสูตร ประเภทวีซ่า ฯลฯ. เจ้าหน้าที่ของเรายินดีที่จะแนะนำคุณเกี่ยวกับขั้นตอนที่เหมาะสมตามสถานการณ์ของคุณ"]},needHelp:{title:"ต้องการความช่วยเหลือ โปรดติดต่อเรา",description:["กฎการขอวีซ่าและขั้นตอนการสมัครแตกต่างกันไปขึ้นอยู่กับสถานะปัจจุบันของคุณ.\u003Cbr \u002F\u003Eหากคุณต้องการคำแนะนำก่อนการสมัคร โปรดติดต่อเรา.\u003Cbr \u002F\u003Eเรามีเจ้าหน้าที่ที่สามารถพูดได้ถึง 8 ภาษา."]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-th.jpg",link:"\u002Fth\u002Fcontact",title:"ติดต่อเรา",lists:[{campus:"\u003Cสาขา Westwood\u003E",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"โทร:310⁻887⁻0777"},{campus:"\u003Cสาขา Hollywood\u003E",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"โทร:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:28.809Z",updatedAt:"2025-05-26T12:06:27.715Z"}}],fetch:{},mutations:void 0});